const habits = ref([{ id: 1, name: 'Read', done: false }, { id: 2, name: 'Run', done: true }])
const remaining = computed(() => habits.value.filter(h => !h.done).length)
function toggle(id) { const h = habits.value.find(h => h.id === id); h.done = !h.done }
toggle(1); toggle(2)
